import React from "react";
import classes from "./Header.module.css";
import { Link } from "react-router-dom";
export const Header = () => {
  return (
    <header className={classes.header}>
      <Link to="/">Коннект</Link>
      <nav>
        <Link to="/">голосование</Link>
        <Link to="/">афиша</Link>
        <Link to="/">обсуждения</Link>
      </nav>
      <button>
        <p>войти</p>
      </button>
    </header>
  );
};
